% Compute power spectrum

% Generated by MATLAB(R) 9.9 and Signal Processing Toolbox 8.5.
% Generated on: 08-Mar-2022 08:52:59

% Parameters
timeLimits = [0 121.76]; % seconds
frequencyLimits = [0 125]; % Hz

%%
% Index into signal time region of interest
or_eeg_ROI = or_eeg(:);
sampleRate = 250; % Hz
startTime = 0; % seconds
minIdx = ceil(max((timeLimits(1)-startTime)*sampleRate,0))+1;
maxIdx = floor(min((timeLimits(2)-startTime)*sampleRate,length(or_eeg_ROI)-1))+1;
or_eeg_ROI = or_eeg_ROI(minIdx:maxIdx);

% Compute spectral estimate
% Run the function call below without output arguments to plot the results
[Por_eeg_ROI, For_eeg_ROI] = pspectrum(or_eeg_ROI,sampleRate, ...
    'FrequencyLimits',frequencyLimits);

%%
% Index into signal time region of interest
pr_eeg_ROI = pr_eeg(:);
sampleRate = 250; % Hz
startTime = 0; % seconds
minIdx = ceil(max((timeLimits(1)-startTime)*sampleRate,0))+1;
maxIdx = floor(min((timeLimits(2)-startTime)*sampleRate,length(pr_eeg_ROI)-1))+1;
pr_eeg_ROI = pr_eeg_ROI(minIdx:maxIdx);

% Compute spectral estimate
% Run the function call below without output arguments to plot the results
[Ppr_eeg_ROI, Fpr_eeg_ROI] = pspectrum(pr_eeg_ROI,sampleRate, ...
    'FrequencyLimits',frequencyLimits);

%% Plot
figure
plot(For_eeg_ROI, log(Por_eeg_ROI))
hold on
plot(Fpr_eeg_ROI, log(Ppr_eeg_ROI))
legend({'original', 'preprocessed'})
xlabel('frequency')
ylabel('power spectrum [dB]')
title('Cz')
xlim([0 125])
ylim([-10 10])
axis square
